// Sidekick-Hund: schaut bei jeder 10. falschen Antwort vom Rand rein und hält sich mit den Pfoten fest
(function(){
  var IMG = "data:image/png;base64,";
  var PFOTE = '<svg class="pfote" viewBox="0 0 70 50" width="70" height="50"><path d="M-10 9 H30 C52 5 66 12 66 25 C66 38 52 45 30 41 H-10 Z" fill="#e4b574" stroke="#111" stroke-width="4" stroke-linejoin="round"/><path d="M30 41 C40 44 50 43 56 38" fill="none" stroke="#d9a867" stroke-width="5" stroke-linecap="round"/><path d="M48 13 L54 18 M51 24 L59 25 M48 36 L54 32" stroke="#111" stroke-width="3.5" stroke-linecap="round"/></svg>';
  var SAETZE = [
    "Wuff! Das hätt ich auch nicht gewusst!",
    "Kopf hoch! Auch Brokkoli wächst nicht an einem Tag.",
    "Wuff… Fehler sind zum Lernen da!",
    "Keine Panik – die kommt am Ende nochmal, dann zeigst du's ihr!",
    "Tief durchatmen, weiter geht's! Wuff!",
    "Psst… ich hab auch schon mal L und N vertauscht."
  ];
  var JEDE = 10;
  var KEY = 'sidekickWrongCount';

  var css = document.createElement('style');
  css.textContent =
    '#sidekick{position:fixed;z-index:99999;top:34%;width:120px;height:270px;pointer-events:none;transition:transform .6s cubic-bezier(.3,1.35,.5,1)}'+
    '#sidekick.l{left:0;transform:translateX(-130px)}'+
    '#sidekick.r{right:0;transform:scaleX(-1) translateX(-130px)}'+
    '#sidekick.l.show{transform:translateX(0)}'+
    '#sidekick.r.show{transform:scaleX(-1) translateX(0)}'+
    '#sidekick img{position:absolute;left:-58px;top:40px;width:160px;transform:rotate(20deg);filter:drop-shadow(0 0 1.5px #111) drop-shadow(0 3px 6px rgba(0,0,0,.35))}'+
    '#sidekick .pfote{position:absolute;left:-26px;filter:drop-shadow(0 2px 3px rgba(0,0,0,.35))}'+
    '#sidekick .p1{top:26px;transform:rotate(-14deg)}'+
    '#sidekick .p2{top:206px;transform:rotate(12deg)}'+
    '#sidekickBubble{position:fixed;z-index:99999;top:calc(34% - 30px);max-width:60vw;background:#fff;color:#222;font:600 15px/1.3 system-ui,sans-serif;padding:10px 13px;border-radius:14px;box-shadow:0 4px 14px rgba(0,0,0,.3);opacity:0;transition:opacity .3s;pointer-events:auto}'+
    '#sidekickBubble.show{opacity:1}'+
    '#sidekickBubble.l{left:118px}#sidekickBubble.r{right:118px}';
  document.head.appendChild(css);

  var busy = false, letzter = -1;
  function zeigen(){
    if(busy) return; busy = true;
    var seite = Math.random() < .5 ? 'l' : 'r';
    var i; do { i = Math.floor(Math.random()*SAETZE.length); } while(i === letzter && SAETZE.length > 1);
    letzter = i;
    var d = document.createElement('div'); d.id = 'sidekick'; d.className = seite;
    d.innerHTML = '<img alt="" src="'+IMG+'">' + PFOTE.replace('class="pfote"','class="pfote p1"') + PFOTE.replace('class="pfote"','class="pfote p2"');
    var b = document.createElement('div'); b.id = 'sidekickBubble'; b.className = seite;
    b.textContent = SAETZE[i];
    document.body.appendChild(d); document.body.appendChild(b);
    var weg = function(){
      b.classList.remove('show'); d.classList.remove('show');
      setTimeout(function(){ d.remove(); b.remove(); busy = false; }, 650);
    };
    b.addEventListener('click', weg);
    requestAnimationFrame(function(){ requestAnimationFrame(function(){
      d.classList.add('show');
      setTimeout(function(){ b.classList.add('show'); }, 500);
    }); });
    setTimeout(weg, 4500);
  }

  function falsch(){
    var n = 0;
    try { n = parseInt(localStorage.getItem(KEY) || '0', 10) || 0; } catch(e){}
    n++;
    try { localStorage.setItem(KEY, String(n)); } catch(e){}
    if(n % JEDE === 0) zeigen();
  }

  window.sidekickZeigen = zeigen; // zum Testen
  if(typeof window.finishAnswer === 'function'){
    var orig = window.finishAnswer;
    window.finishAnswer = function(card, correct){
      var r = orig.apply(this, arguments);
      if(!correct) setTimeout(falsch, 300);
      return r;
    };
  }
})();
